@Component("subscriber-entity-projector")
public class SubscriberEntityProjector implements EntityProjector<Subscriber>{
		
	// core constructor
	public SubscriberEntityProjector(ProjectorRegistry registry,
										SubscriberRepository repository ) {
        this.registry 	= registry;
		this.repository = repository;
    }

	@Override
	public Class<Subscriber> getEntityClass() {
		return Subscriber.class;
	}

    /*
	 * Insert a Subscriber
	 * 
     * @param	entity Subscriber
     */
    public Subscriber create( Subscriber entity) {
	    LOGGER.info("creating " + entity.toString() );
	   
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    return repository.save(entity);
        
    }

	/*
	 * Update a Subscriber
	 * 
     * @param	entity Subscriber
     */
    public Subscriber update( Subscriber entity) {
	    LOGGER.info("updating " + entity.toString() );

	    // ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		return repository.save(entity);

    }
    
	/*
	 * Delete a Subscriber
	 * 
     * @param	id		UUID
     */
    public Subscriber delete( UUID id ) {
	    LOGGER.info("deleting " + id.toString() );

    	// ------------------------------------------
    	// locate the entity by the provided id
    	// ------------------------------------------
	    Subscriber entity = repository.findById(id).get();
	    
    	// ------------------------------------------
    	// delete what is discovered 
    	// ------------------------------------------
    	repository.delete( entity );
    	
    	return entity;
    }    


    /*
     * Add to the Alerts
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Subscriber
     */
    public Subscriber addToAlerts( UUID parentId, Alert addTo ) {
	    LOGGER.info("handling AssignAlertsToSubscriberEvent - " );
	    
	    Subscriber parentEntity = repository.findById(parentId).get();
	    Alert child = registry.project( Alert.class, addTo.getAlertId());
	    
	    parentEntity.getAlerts().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Alerts
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Subscriber
     */
	public Subscriber removeFromAlerts( UUID parentId, Alert removeFrom ) {
	    LOGGER.info("handling RemoveAlertsFromSubscriberEvent " );
	
	    Subscriber parentEntity = repository.findById(parentId).get();
	    Alert child = registry.project( Alert.class, removeFrom.getAlertId());
	    
	    parentEntity.getAlerts().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



    /**
     * Method to retrieve the Subscriber via an FindSubscriberQuery
     * @return 	query	FindSubscriberQuery
     */
    @SuppressWarnings("unused")
    public Subscriber find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Subscriber - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Subscribers
     *
     * @param	query	FindAllSubscriberQuery 
     * @return 	List<Subscriber> 
     */
    @SuppressWarnings("unused")
    public List<Subscriber> findAll( FindAllSubscriberQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Subscriber - {0}", exc.getMessage() );
    	}
    	return null;
    }


    //--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
    protected final SubscriberRepository repository;
	protected final ProjectorRegistry registry;


    private static final Logger LOGGER 	= LoggerFactory.getLogger(SubscriberEntityProjector.class.getName());

}
